// TestProbeImage is the table test for probeImage (B05, B06, B07): a stdlib-
// generated jpeg/png yields JSON {width,height,format}; HEIC/webp (no stdlib
// decoder) and a missing file SOFT-FAIL (empty data + a warning + nil err, mirroring
// probe / ffprobe.go INV3). webp soft-fails here because image/webp is not a stdlib
// package (see image.go NOTE); exiftool supplies webp data at enrichment.
func TestProbeImage(t *testing.T) {
	root := t.TempDir()
	jpg := filepath.Join(root, "a.jpg")
	writeImg(t, jpg, "jpeg", 5, 3)
	pngPath := filepath.Join(root, "a.png")
	writeImg(t, pngPath, "png", 4, 2)
	if err := os.WriteFile(filepath.Join(root, "x.heic"), []byte("not really heic"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "y.webp"), []byte("not really webp"), 0o644); err != nil {
		t.Fatal(err)
	}

	tests := []struct {
		name       string
		path       string
		wantData   bool // expect non-empty {width,height,format}
		wantFormat string
	}{
		{name: "jpeg_dims", path: jpg, wantData: true, wantFormat: "jpeg"},
		{name: "png_dims", path: pngPath, wantData: true, wantFormat: "png"},
		{name: "heic_softfail", path: filepath.Join(root, "x.heic"), wantData: false},
		{name: "webp_softfail", path: filepath.Join(root, "y.webp"), wantData: false},
		{name: "missing_softfail", path: filepath.Join(root, "nope.jpg"), wantData: false},
	}
	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			data, warning, err := probeImage(context.Background(), tc.path)
			if err != nil {
				t.Fatalf("probeImage err = %v, want nil (INV3 soft-fail)", err)
			}
			if !tc.wantData {
				if len(data) != 0 {
					t.Fatalf("data = %s, want empty (soft-fail)", data)
				}
				if warning == "" {
					t.Fatal("warning empty, want a soft-fail reason")
				}
				return
			}
			if len(data) == 0 {
				t.Fatalf("data empty, want {width,height,format}")
			}
			if warning != "" {
				t.Fatalf("warning = %q, want none for a valid image", warning)
			}
			m := decodeJSON(t, data)
			if got := m["format"]; got != tc.wantFormat {
				t.Errorf("format = %v, want %q", got, tc.wantFormat)
			}
			for _, k := range []string{"width", "height"} {
				if _, ok := m[k]; !ok {
					t.Errorf("missing %q in %v", k, m)
				}
			}
		})
	}
}

// TestImageMime_IsImage covers imageMime (6 extensions) + isImage's ASCII-extension
// lowercasing (a Cyrillic-stemmed .jpg is still an image — B08/AC-unicode).
func TestImageMime_IsImage(t *testing.T) {
	for _, ext := range []string{".jpg", ".jpeg", ".png", ".webp", ".heic", ".heif"} {
		if !isImage("anything" + ext) {
			t.Errorf("isImage(%q) = false, want true", "anything"+ext)
		}
		if imageMimeOf("anything"+ext) == "" {
			t.Errorf("imageMimeOf(%q) empty, want a MIME type", "anything"+ext)
		}
	}
	for _, ext := range []string{".mkv", ".mp4", ".nfo", ""} {
		if isImage("anything" + ext) {
			t.Errorf("isImage(%q) = true, want false", "anything"+ext)
		}
	}
	// Cyrillic stem, ASCII dotted extension — lowercasing touches .jpg only.
	if !isImage("Фото.jpg") {
		t.Error(`isImage("Фото.jpg") = false, want true (ASCII ext only)`)
	}
}

// TestWalk_ModuleTypeGating covers B01-B03 + B04: an image library discovers ONLY
// image files (a stray .mkv is skipped — B02); a TV library is unchanged (cover
// .jpg is NOT discovered — B03, R-I4 no-regression); and an image file's base info
// comes from probeImage (stdlib {format:jpeg}), NOT ffprobe (B04).
func TestWalk_ModuleTypeGating(t *testing.T) {
	root := t.TempDir()
	// Image library tree: one real jpg (stdlib-decodable) + one mkv (must be filtered).
	jpg := filepath.Join(root, "IMG.jpg")
	writeImg(t, jpg, "jpeg", 6, 4)
	if err := os.WriteFile(filepath.Join(root, "clip.mkv"), []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}

	t.Run("image_mode_discovers_only_images", func(t *testing.T) {
		// walk expects the RESOLVED root (scanner.Scan runs resolveRoot first,
		// which EvalSymlinks the temp dir on macOS so withinRoot accepts it).
		resolved, err := resolveRoot(root)
		if err != nil {
			t.Fatalf("resolveRoot: %v", err)
		}
		ch := walk(context.Background(), resolved, "image", nil)
		got := drain(ch)
		if len(got) != 1 || got[0].GetRelativePath() != "IMG.jpg" {
			t.Fatalf("image walk = %d files %v, want exactly {IMG.jpg} (.mkv must be filtered)", len(got), rels(got))
		}
		// B04: base info via stdlib probeImage, NOT ffprobe — format is "jpeg".
		m := decodeJSON(t, got[0].GetFfprobeJson())
		if got := m["format"]; got != "jpeg" {
			t.Errorf("image ffprobe_json format = %v, want jpeg (stdlib probeImage, not ffprobe)", got)
		}
	})

	t.Run("tv_mode_discovers_only_video_no_coverart", func(t *testing.T) {
		tvRoot := t.TempDir()
		if err := os.WriteFile(filepath.Join(tvRoot, "cover.jpg"), []byte("cover"), 0o644); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(tvRoot, "show.mkv"), []byte("show"), 0o644); err != nil {
			t.Fatal(err)
		}
		resolved, err := resolveRoot(tvRoot)
		if err != nil {
			t.Fatalf("resolveRoot: %v", err)
		}
		ch := walk(context.Background(), resolved, "tv", nil)
		got := drain(ch)
		rels := rels(got)
		if len(rels) != 1 || rels[0] != "show.mkv" {
			t.Fatalf("tv walk = %v, want exactly {show.mkv} (cover.jpg must NOT be discovered — R-I4)", rels)
		}
	})
}

// TestScan_ForwardsModuleType covers B09: scannerImpl.Scan forwards
// req.GetModuleType() into walk, so an image ScanRequest selects the image map.
func TestScan_ForwardsModuleType(t *testing.T) {
	root := t.TempDir()
	jpg := filepath.Join(root, "pic.jpg")
	writeImg(t, jpg, "jpeg", 3, 3)
	if err := os.WriteFile(filepath.Join(root, "video.mkv"), []byte("v"), 0o644); err != nil {
		t.Fatal(err)
	}
	s := &scannerImpl{}
	ch, err := s.Scan(context.Background(), &scannerv1.ScanRequest{LibraryPath: root, ModuleType: "image"})
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	got := drain(ch)
	if len(got) != 1 || got[0].GetRelativePath() != "pic.jpg" {
		t.Fatalf("image Scan = %v, want exactly {pic.jpg} (module_type forwarded into walk)", rels(got))
	}
}

// drain collects all DiscoveredFile from a walk channel.
func drain(ch <-chan *scannerv1.DiscoveredFile) []*scannerv1.DiscoveredFile {
	var out []*scannerv1.DiscoveredFile
	for f := range ch {
		out = append(out, f)
	}
	return out
}

// rels returns the relative-path slice of the discovered files.
func rels(fs []*scannerv1.DiscoveredFile) []string {
	out := make([]string, 0, len(fs))
	for _, f := range fs {
		out = append(out, f.GetRelativePath())
	}
	return out
}

// decodeJSON unmarshals a probe JSON blob into a map. Test helper.
func decodeJSON(t *testing.T, b []byte) map[string]any {
	t.Helper()
	m := map[string]any{}
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("decode probe json: %v (raw=%s)", err, b)
	}
	return m
}

// writeImg generates a tiny valid image (w x h) at path in the given stdlib
// format ("jpeg"|"png"). Fixed dimensions keep assertions stable.
func writeImg(t *testing.T, path, format string, w, h int) {
	t.Helper()
	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create %s: %v", format, err)
	}
	defer f.Close()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, color.RGBA{R: uint8(x * 20), G: uint8(y * 20), B: 64, A: 255})
		}
	}
	switch format {
	case "jpeg":
		if err := jpeg.Encode(f, img, nil); err != nil {
			t.Fatalf("encode jpeg: %v", err)
		}
	case "png":
		if err := png.Encode(f, img); err != nil {
			t.Fatalf("encode png: %v", err)
		}
	default:
		t.Fatalf("writeImg: unknown format %q", format)
	}
}
